/// event-turn: the turn Hermes runs on its own when a delegated subagent ends
/// (`async_delegation_complete`), started after the socket was renewed since
/// the previous turn closed: same server numbering, another transport.
class _EventTurnSuccessorGateway extends _SequencedSuccessorGateway
    implements HermesDesktopRecoverySessionLifecycleGateway {
  bool serverRunning = false;
  int recoveryReads = 0;

  @override
  Future<DesktopSessionSnapshot> resumeExistingForRecovery(
    String storedSessionId, {
    String profile = '',
  }) async {
    recoveryReads += 1;
    return DesktopSessionSnapshot(
      runtimeSessionId: 'runtime-ui-test',
      storedSessionId: storedSessionId,
      created: false,
      running: serverRunning,
      status: serverRunning ? 'working' : 'idle',
    );
  }

  @override
  // ignore: deprecated_member_use_from_same_package
  void commitRecoveryRuntime(String runtimeSessionId) {}
}

class _StableRefreshGateway extends _UiRewindGateway
    implements
        HermesDesktopSubagentGateway,
        HermesDesktopControlGateway,
        HermesDesktopSessionControlGateway {
  _StableRefreshGateway({
    this.subagents = const [
      DesktopSubagentSnapshot(
        subagentId: 'stable-refresh-child',
        status: 'running',
        goal: 'Actividad estable',
      ),
    ],
  });

  List<DesktopSubagentSnapshot> subagents;
  Completer<List<DesktopSubagentSnapshot>>? listGate;
  AgentCenterSnapshot processSnapshot = const AgentCenterSnapshot(
    snapshots: [],
    processes: [],
  );
  Object? processListError;
  int processListCalls = 0;
  int controlReadCalls = 0;
  int inFlightControlReadCalls = 0;
  int maxActiveControlReadCalls = 0;
  Completer<SessionControlSnapshot>? controlReadGate;
  Object? controlReadError;
  SessionControlSnapshot controlSnapshot = const SessionControlSnapshot(
    goal: null,
    loop: null,
    heartbeat: null,
    revision: '',
    updatedAt: null,
  );
  final List<String> controlActions = [];
  final List<String> killedProcesses = [];
  int listCalls = 0;
  int inFlightSubagentListCalls = 0;
  int maxActiveListCalls = 0;
  final List<String> subagentListRuntimes = [];

  @override
  Future<List<DesktopSubagentSnapshot>> listSubagents(
    String runtimeSessionId,
  ) async {
    listCalls += 1;
    inFlightSubagentListCalls += 1;
    if (inFlightSubagentListCalls > maxActiveListCalls) {
      maxActiveListCalls = inFlightSubagentListCalls;
    }
    subagentListRuntimes.add(runtimeSessionId);
    try {
      final gate = listGate;
      if (gate != null) {
        final result = await gate.future;
        if (identical(listGate, gate)) listGate = null;
        return result;
      }
      return subagents;
    } finally {
      inFlightSubagentListCalls -= 1;
    }
  }

  @override
  Future<AgentCenterSnapshot> agentCenterSnapshot({
    String runtimeSessionId = '',
  }) async {
    processListCalls += 1;
    final error = processListError;
    if (error != null) throw error;
    return processSnapshot;
  }

  @override
  Future<SessionControlSnapshot> readSessionControl(
    String runtimeSessionId,
  ) async {
    controlReadCalls += 1;
    inFlightControlReadCalls += 1;
    if (inFlightControlReadCalls > maxActiveControlReadCalls) {
      maxActiveControlReadCalls = inFlightControlReadCalls;
    }
    try {
      final error = controlReadError;
      if (error != null) throw error;
      final gate = controlReadGate;
      if (gate != null) {
        final result = await gate.future;
        if (identical(controlReadGate, gate)) controlReadGate = null;
        return result;
      }
      return controlSnapshot;
    } finally {
      inFlightControlReadCalls -= 1;
    }
  }

  @override
  Future<void> sendSessionControlAction(
    String runtimeSessionId,
    String action,
  ) async {
    controlActions.add(action);
  }

  @override
  Future<void> killBackgroundProcess(
    String runtimeSessionId,
    String processId,
  ) async {
    killedProcesses.add(processId);
  }

  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);

  @override
  Future<DesktopSubagentTailResult> tailSubagent(
    String runtimeSessionId,
    String subagentId,
  ) async => const DesktopSubagentTailResult(
    available: false,
    content: '',
    truncated: false,
  );

  @override
  Future<DesktopSubagentSteerResult> steerSubagent(
    String runtimeSessionId,
    String subagentId,
    String text,
  ) async => DesktopSubagentSteerResult(
    status: 'queued',
    subagentId: subagentId,
    text: text,
  );

  @override
  Future<DesktopSubagentInterruptResult> interruptSubagent(
    String runtimeSessionId,
    String subagentId,
  ) async =>
      DesktopSubagentInterruptResult(found: true, subagentId: subagentId);
}

class _RestoredApprovalUiGateway extends _UiRewindGateway
    implements HermesDesktopApprovalResultGateway {
