/// Gateway that also speaks the side-agent and branch RPCs.
class _UiTurnSideGateway extends _NoLiveMutationGateway
    implements HermesDesktopTurnSideGateway {
  final List<({String method, Map<String, Object?> params})> sideCalls = [];
  Object? sideFailure;
  int branchCount = 0;

  @override
  bool turnSideKnownUnsupported = false;
  @override
  bool turnBranchKnownUnsupported = false;

  void _fail() {
    final failure = sideFailure;
    if (failure == null) return;
    sideFailure = null;
    if (failure is DesktopControlFailure &&
        failure.kind == DesktopControlFailureKind.unsupported) {
      turnSideKnownUnsupported = true;
    }
    throw failure;
  }

  @override
  Future<String> askSideQuestion(String runtimeSessionId, String text) async {
    sideCalls.add((
      method: 'prompt.btw',
      params: {'session_id': runtimeSessionId, 'text': text},
    ));
    _fail();
    return 'btw-task';
  }

  @override
  Future<String> startBackgroundPrompt(
    String runtimeSessionId,
    String text,
  ) async {
    sideCalls.add((
      method: 'prompt.background',
      params: {'session_id': runtimeSessionId, 'text': text},
    ));
    _fail();
    return 'bg-task';
  }

  Future<DesktopBranchResult> _branch(
    String method,
    Map<String, Object?> params,
  ) async {
    sideCalls.add((method: method, params: params));
    branchCount++;
    return DesktopBranchResult(
      runtimeSessionId: 'runtime-child-$branchCount',
      storedSessionId: 'stored-child-$branchCount',
      title: 'Child',
      messageCount: 2,
    );
  }

  @override
  Future<DesktopBranchResult> branchSession(
    String runtimeSessionId, {
    int? count,
    String? name,
    required String idempotencyKey,
  }) => _branch('session.branch', {
    'session_id': runtimeSessionId,
    'count': ?count,
    'idempotency_key': idempotencyKey,
  });

  @override
  Future<DesktopBranchResult> branchWholeSession(
    String runtimeSessionId, {
    String? name,
    required String idempotencyKey,
  }) => _branch('session.branch_whole', {
    'session_id': runtimeSessionId,
    'idempotency_key': idempotencyKey,
  });
}

class _UiNativeCompressionGateway extends _UiRewindGateway
    implements HermesDesktopCompressionGateway {
  _UiNativeCompressionGateway(this.compressionResult);

  DesktopCompressionResult compressionResult;
  Map<String, dynamic>? compressionWireResult;
  Completer<Map<String, dynamic>>? compressionWireGate;
  Completer<DesktopCompressionResult>? nativeCompressionGate;
  final compressionEntered = Completer<void>();
  int nativeCompressionCalls = 0;

  @override
  Future<DesktopCompressionResult> compressSession(
    String runtimeSessionId, {
    String focusTopic = '',
  }) async {
    nativeCompressionCalls += 1;
    if (!compressionEntered.isCompleted) compressionEntered.complete();
    if (compressionWireGate case final wireGate?) {
      return DesktopCompressionResult.fromJson(await wireGate.future);
    }
    final gate = nativeCompressionGate;
    if (gate != null) return gate.future;
    final wire = compressionWireResult;
    return wire == null
        ? compressionResult
        : DesktopCompressionResult.fromJson(wire);
  }
}

DesktopCompressionResult _uiNativeCompressionResult(
  DesktopCompressionStatus status,
) => switch (status) {
  DesktopCompressionStatus.compressed => DesktopCompressionResult.fromJson({
    'status': 'compressed',
    'summary': {'noop': false},
    'info': {'stored_session_id': 'stored-ui-native-compressed'},
    'messages': <Object>[],
  }),
  DesktopCompressionStatus.noOp => DesktopCompressionResult.fromJson({
    'status': 'compressed',
    'removed': 0,
    'before_messages': 1,
    'after_messages': 1,
    'before_tokens': 10,
    'after_tokens': 10,
    'summary': {'noop': true},
  }),
  DesktopCompressionStatus.aborted => DesktopCompressionResult.fromJson({
    'status': 'aborted',
    'summary': {'aborted': true},
    'info': {'stored_session_id': 'stored-ui-native-aborted'},
    'messages': <Object>[],
  }),
  DesktopCompressionStatus.pending => DesktopCompressionResult.fromJson({
    'status': 'pending',
    'turn_isolation': true,
    'message': 'compression still running in the background',
  }),
  DesktopCompressionStatus.lockHeld => DesktopCompressionResult.fromJson({
    'compressed': false,
    'lock_held': true,
    'message': 'private holder data',
  }),
};

class _ReplayProbeUiGateway extends _UiRewindGateway
    implements HermesDesktopCompressionStatusGateway {
  final replayRuntimeIds = <String>[];

  /// `running`: the ring still pins compressing; `done`: ready followed;
  /// `gone`: the gateway never saw the runtime (restart / eviction).
  String state = 'running';

  @override
  Future<Map<String, dynamic>> compressionEventReplay(
    String runtimeSessionId,
  ) async {
    replayRuntimeIds.add(runtimeSessionId);
    if (state == 'gone') {
      return {'events': <Object>[], 'latest_seq': 0, 'truncated': false};
    }
    return {
      'events': [
        {
          'type': 'status.update',
          'session_id': runtimeSessionId,
          'seq': 1,
          'payload': {
            'kind': 'compressing',
            'text': 'compressing 35 messages (~20,379 tok)',
          },
        },
        if (state == 'done')
          {
            'type': 'status.update',
            'session_id': runtimeSessionId,
            'seq': 2,
            'payload': {'kind': 'status', 'text': 'ready'},
          },
      ],
      'latest_seq': state == 'done' ? 2 : 1,
      'truncated': false,
      'epoch': 'epoch-a',
    };
  }
}

