        .setMockMethodCallHandler(MethodChannel(name), (_) async => null);
  }

  tearDown(() => StepsBarMemory.openByDefault = false);
  // These tests pin how many times the adaptive snapshot reads
  // `subagent.list` (mount, 5/15/30 s eventless ladder, covered route,
  // pause/resume). The visible chat's own 5 s roster poll (Desktop
  // use-subagent-snapshot.ts) would add reads on top; it has its own tests
  // in subagent_roster_poll_test.dart.
  setUp(() => ChatScreen.subagentRosterPollInterval = null);
  tearDown(
    () => ChatScreen.subagentRosterPollInterval = const Duration(seconds: 5),
  );

  setUp(() {
    // The calls of a turn are rows of a summary bar that starts closed; these
    // chat tests read and tap those rows, so their bars start open (the bar's
    // own closed start and memory are tested in steps_bar_test.dart).
    StepsBarMemory.reset();
    StepsBarMemory.openByDefault = true;
    // Caché estática de planes de render: cada test empieza vacío.
    ChatScreen.resetAssistantRenderPlanCacheForTesting();
    BotMentionRoster.shared.clear();
    secureStore = <String, String>{};
    failOutboxWrites = false;
    outboxWriteCalls = 0;
    delayedOutboxRead = null;
    delayedOutboxWrite = null;
    clipboardText = null;
    foregroundServiceRunning = false;
    hapticCalls = 0;
    TurnOutboxStore.resetSerializationForTesting();
    TestWidgetsFlutterBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(SystemChannels.platform, (call) async {
          switch (call.method) {
            case 'Clipboard.setData':
              clipboardText = (call.arguments as Map?)?['text'] as String?;
              return null;
            case 'Clipboard.getData':
              return clipboardText == null
                  ? null
                  : <String, dynamic>{'text': clipboardText};
            case 'HapticFeedback.vibrate':
              hapticCalls += 1;
              return null;
          }
          return null;
        });
    TestWidgetsFlutterBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(
          const MethodChannel('plugins.it_nomads.com/flutter_secure_storage'),
          (call) async {
            final args =
                (call.arguments as Map?)?.cast<String, dynamic>() ?? {};
            switch (call.method) {
              case 'write':
                if (failOutboxWrites && args['key'] == 'chat_turn_outbox_v1') {
                  throw PlatformException(code: 'secure_unavailable');
                }
                if (args['key'] == 'chat_turn_outbox_v1') {
                  outboxWriteCalls++;
                  final writeGate = delayedOutboxWrite;
                  if (writeGate != null) await writeGate.future;
                }
                secureStore[args['key'] as String] = args['value'] as String;
                return null;
              case 'read':
                final key = args['key'] as String;
                if (key == 'chat_turn_outbox_v1' && delayedOutboxRead != null) {
                  return delayedOutboxRead!.future;
                }
                return secureStore[key];
              case 'delete':
                secureStore.remove(args['key'] as String);
                return null;
              case 'readAll':
                return Map<String, String>.from(secureStore);
              case 'containsKey':
                return secureStore.containsKey(args['key'] as String);
            }
            return null;
          },
        );
    mockChannel('dexterous.com/flutter/local_notifications');
    TestWidgetsFlutterBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(
          const MethodChannel('flutter_foreground_task/methods'),
          (call) async {
            // Imita el ciclo real del servicio. Responder siempre `false`
            // dejaba al plugin sondeando cinco segundos después de un start y
            // ocultaba las carreras App Lock -> pausa -> Continuar.
            switch (call.method) {
              case 'isRunningService':
                return foregroundServiceRunning;
              case 'startService':
              case 'restartService':
                foregroundServiceRunning = true;
                return null;
              case 'stopService':
                foregroundServiceRunning = false;
                return null;
              case 'attachedActivity':
                return true;
            }
            return null;
          },
        );
    mockChannel('flutter_foreground_task/background');
  });

