  /// Monta el HermesApp real (saltando onboarding) y empuja ChatScreen
  /// sobre su Navigator. `messages` siembra el ActiveChat de la sesión.
  Future<ActiveChat> pumpChat(
    WidgetTester tester, {
    List<Map<String, dynamic>> messages = const [],
    SttEngine? stt,
    SshSessionService Function(SshManager)? sshSessionFactory,
    ChatPipelineState chatState = ChatPipelineState.idle,
    HermesDesktopGateway? desktopGateway,
    SavedConnection? connection,
    Session? session,
    bool messagesLoaded = true,
    String? initialPrompt,
    bool initialVoiceMode = false,
    bool requestComposerFocus = false,
    bool? legacyConversationEnabled,
    ChatPerformanceProbe? performanceProbe,
    ApiClient? api,
    Map<String, Object> initialPreferences = const {},
    String? initialActiveProfile,
    bool preAttach = true,
    bool acquireDesktopRuntimeBeforeMount = false,
    bool attachDesktopRuntimeOnLoad = true,
    bool allowUnownedDesktopSnapshotForTesting = true,
    Future<AttachmentDraft?> Function(AttachmentDraft)? attachmentMaterializer,
    Future<bool> Function(AttachmentDraft)? attachmentPrivateCopyDeleter,
    Future<void> Function()? cancelStreamOverride,
    VoidCallback? sendAttemptObserver,
    Future<bool> Function()? turnIdempotencyCapability,
    StoredSessionMessageLoader? storedMessageLoader,
    String? initialStoredSessionId,
    AgentProfile? missionBotProfile,
    MissionProfileAvatarCache? missionAvatarCache,
    CompressionRestoreStore? compressionRestoreStore,
    FlutterSecureStorage? draftSecureStorage,
    VoidCallback? beforeChatPush,
    Duration chatRouteTransition = const Duration(milliseconds: 350),
    bool registerActiveChatsTearDown = true,
    int transcriptPageSizeForTesting = 120,
    int Function()? wallClockMs,
    Future<void> Function(String path, File destination)?
    userServerMediaFetcher,
    Future<void> Function(String path, File destination)? generatedMediaFetcher,
    String? newChatWorkspace,
    Map<ModelPickerSource, ModelPickerFallback>? modelPickerFallbacks,
    DashboardClient Function(SavedConnection)? providerReauthClientFactory,
    DashboardClient? transcriptDashboard,
  }) async {
    // Forzar locale español para que las cadenas i18n de ChatScreen coincidan
    // con las expectativas del test (el test fue escrito en español).
    tester.platformDispatcher.localesTestValue = [const Locale('es')];
    addTearDown(tester.platformDispatcher.clearLocalesTestValue);

    SharedPreferences.setMockInitialValues({
      ...initialPreferences,
      'onboarding_done': true,
      'voice_conversation_enabled': ?legacyConversationEnabled,
    });
    final prefs = await SharedPreferences.getInstance();
    final seededV3Drafts = Map<String, String>.fromEntries(
      secureStore.entries.where(
        (entry) => entry.key.startsWith('chat_draft_v3.'),
      ),
    );
    final connManager = await ConnectionManager.create(prefs);
    final draftStore = ChatDraftStore(
      prefs,
      secureStorage:
          draftSecureStorage ?? _MemoryDraftSecureStorage(secureStore),
      mutationNamespaceForTesting: 'chat-screen-${++draftStoreNamespace}',
    );
    final sec = SecureStorage();
    final activeChats = ActiveChatService(
      attachDesktopRuntimeOnLoad: attachDesktopRuntimeOnLoad,
      compressionRestoreStore:
          compressionRestoreStore ??
          CompressionRestoreStore(
            storage: FlutterSecureCompressionRestoreStorage(
              secureStorage: _MemoryDraftSecureStorage(secureStore),
            ),
            mutationNamespaceForTesting:
                'chat-screen-compression-${++compressionRestoreStoreNamespace}',
          ),
    );
    if (registerActiveChatsTearDown) addTearDown(activeChats.dispose);
    final targetConnection = connection ?? _conn();
    final targetSession = session ?? _session();
    if (initialActiveProfile != null) {
      await connManager.setActiveProfile(
        targetConnection.id,
        initialActiveProfile,
      );
    }

    // Pre-adjunta la sesión con mensajes ya cargados: ChatScreen reusará este
    // chat y no disparará la recarga de red.
    late ActiveChat chat;
    if (preAttach) {
      chat = activeChats.attach(
        connection: targetConnection,
        sessionId: targetSession.id,
        logicalSessionId: targetSession.logicalId,
        sessionTitle: targetSession.displayTitle,
        sessionProfile: targetSession.profile,
        initialStoredSessionId: initialStoredSessionId,
        api: api ?? _safeApi(),
        desktopGateway: desktopGateway,
        attachDesktopRuntimeOnLoad: attachDesktopRuntimeOnLoad,
        allowUnownedDesktopSnapshotForTesting:
            allowUnownedDesktopSnapshotForTesting,
        storedMessageLoader: storedMessageLoader,
        turnIdempotencyCapability: turnIdempotencyCapability,
        disableForegroundKeepAlive: desktopGateway != null,
        transcriptPageSizeForTesting: transcriptPageSizeForTesting,
        wallClockMsForTesting: wallClockMs,
        transcriptDashboard: transcriptDashboard,
      );
      chat.internalMessagesForTesting = List<Map<String, dynamic>>.from(
        messages,
      );
      chat.messagesLoaded = messagesLoaded;
      chat.state = chatState;
      if (acquireDesktopRuntimeBeforeMount) {
        final acquired = await chat.ensureDesktopRuntime(
          acquireForExplicitAction: true,
        );
        if (!acquired) {
          throw StateError('El fixture no pudo adquirir el runtime Desktop');
        }
      }
    }

    final notifications = NotificationService(
      prefs,
      deliveryStore: _sharedDeliveryStore,
    );
    await tester.pumpWidget(
      HermesApp(
        connManager: connManager,
        appLock: AppLockService(prefs),
        approvalPolicy: ApprovalPolicyService(prefs),
        fontSize: FontSizeService(prefs),

        sshManager: SshManager(sec, connManager),
        sftpTransfers: SftpTransferService(
          SshManager(sec, connManager),
          NotificationService(prefs),
        ),
        sshSessions:
            sshSessionFactory?.call(SshManager(sec, connManager)) ??
            SshSessionService(SshManager(sec, connManager)),
        notifications: notifications,
        activeChats: activeChats,
      ),
    );
    // Deja pasar la transición de entrada, la carga inicial de Home y la
    // init diferida de notificaciones: la raíz queda estable antes de medir
    // rebuilds propios del chat.
    await tester.pump();
    await tester.pump(const Duration(seconds: 4));
    await tester.pump(const Duration(milliseconds: 400));
    await tester.pump(const Duration(milliseconds: 400));
    await tester.pump(const Duration(milliseconds: 500));

    if (stt != null) {
      tester
          .state<HermesAppState>(find.byType(HermesApp))
          .voice
          .debugSttFactory = () =>
          stt;
    }

    // Empuja ChatScreen sobre el Navigator del HermesApp usando un contexto del
    // árbol ya montado (así queda bajo HermesAppState).
    // Esta suite prueba Chat, no la poda de conexiones huérfanas ni callbacks
    // tardíos del Chat anterior. Inyecta el estado inicial V3 después de que el
    // bootstrap haya asentado, inmediatamente antes de montar el sujeto.
    secureStore.addAll(seededV3Drafts);
    beforeChatPush?.call();
    final ctx = tester.element(find.byType(Navigator).first);
    Navigator.of(ctx).push(
      MaterialPageRoute(
        builder: (_) => ChatScreen(
          connection: targetConnection,
          session: targetSession,
          initialPrompt: initialPrompt,
          initialVoiceMode: initialVoiceMode,
          requestComposerFocus: requestComposerFocus,
          performanceProbe: performanceProbe,
          attachmentMaterializer: attachmentMaterializer,
          attachmentPrivateCopyDeleter: attachmentPrivateCopyDeleter,
          cancelStreamOverride: cancelStreamOverride,
          sendAttemptObserver: sendAttemptObserver,
          initialStoredSessionId: initialStoredSessionId,
          missionBotProfile: missionBotProfile,
          missionAvatarCache: missionAvatarCache,
          draftStoreOverride: draftStore,
          userServerMediaFetcher: userServerMediaFetcher,
          generatedMediaFetcher: generatedMediaFetcher,
          newChatWorkspace: newChatWorkspace,
          modelPickerFallbacks: modelPickerFallbacks,
          providerReauthClientFactory: providerReauthClientFactory,
        ),
      ),
    );
    await tester.pump(); // procesa la navegación
    await tester.pump(chatRouteTransition); // transición de ruta
    if (!preAttach) {
      chat =
          activeChats.of(targetConnection.id, targetSession.id) ??
          (throw StateError('ChatScreen no enlazó la sesión esperada'));
    }
    addTearDown(() async {
      await tester.pumpWidget(const SizedBox.shrink());
      await tester.pump();
    });
    if (StepsBarMemory.openByDefault) await openInlineDetails(tester);
    return chat;
  }

  void mockCompanionStorage() {
    final support = Directory.systemTemp.createTempSync(
      'chat-single-sprite-companion-',
    );
    const channel = MethodChannel('plugins.flutter.io/path_provider');
    TestWidgetsFlutterBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(channel, (call) async => support.path);
    addTearDown(() {
      TestWidgetsFlutterBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(channel, null);
      if (support.existsSync()) support.deleteSync(recursive: true);
    });
  }

  Future<void> enableFullCompanion(WidgetTester tester) async {
    final companion = tester
        .state<HermesAppState>(find.byType(HermesApp))
        .companion;
    await _pumpUntilRealWork(
      tester,
      () => companion.isInitialized,
      real: const Duration(milliseconds: 10),
    );
    expect(companion.isInitialized, isTrue);
    await companion.setPresenceLevel(CompanionPresenceLevel.full);
    // The pet on the island is the profile's identity, read from the
    // profile's own stores: here the profile has one.
    ProfileIdentities.instance.publish(
      tester.widget<ChatScreen>(find.byType(ChatScreen)).connection.id,
      'default',
      _islandPet('profile-pet'),
    );
    addTearDown(ProfileIdentities.instance.reset);
    await tester.pump();
  }

  // Owner (1.2.15): the sprite stands centred ON the island, whole, at
  // 48 dp, and never moves. The island under it is the profile's name.
  testWidgets('island sprite: the assigned companion stands on the island, '
      'whole, at 48 dp', (tester) async {
    final renderDir = Platform.environment['SPRITE_PILL_RENDER_DIR'];
    if (renderDir != null && renderDir.isNotEmpty) await loadDesignFonts();
    addTearDown(tester.platformDispatcher.clearTextScaleFactorTestValue);
    tester.view.physicalSize = const Size(360, 800);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    mockCompanionStorage();
    await pumpChat(
      tester,
      connection: _remoteConn('chatpill-idle'),
      messagesLoaded: true,
      initialPreferences: const {'companion.presence_level': 'full'},
    );
    await enableFullCompanion(tester);
    final face = find.byKey(const ValueKey('chat-header-companion'));
    final slot = find.byKey(const ValueKey('chat-pill-identity-slot'));
    final island = find.byKey(const ValueKey('island'));
    expect(face, findsOneWidget);
    expect(island, findsOneWidget);
    void standsOnIsland() {
      final slotRect = tester.getRect(slot);
      final faceRect = tester.getRect(face);
      final islandRect = tester.getRect(island);
      expect(slotRect.size, const Size.square(48));
      expect(slotRect.center.dx, closeTo(islandRect.center.dx, 0.5));
      // Vistas v3: [Vistas] [Ajustes] leave 360 dp too narrow for the
      // screen's centre (`FloatingChatHeader.minCentredIslandWidth`): the
      // island centres between its buttons, where it was centred between
      // «≡» and «+».
      final between =
          (tester
                  .getRect(find.byKey(const ValueKey('chat-menu-button')))
                  .right +
              tester
                  .getRect(find.byKey(const ValueKey('chat-views-button')))
                  .left) /
          2;
      expect(slotRect.center.dx, closeTo(between, 0.5), reason: 'centred');
      // Its feet on the island's top edge, the rest of it above: never
      // inside the pill, never under the status bar.
      expect(slotRect.bottom - islandRect.top, FloatingChatHeader.faceOverlap);
      expect(slotRect.top, greaterThanOrEqualTo(0));
      // Whole: nothing of it outside its 48 dp.
      expect(slotRect.inflate(0.5).contains(faceRect.topLeft), isTrue);
      expect(slotRect.inflate(0.5).contains(faceRect.bottomRight), isTrue);
      expect(faceRect.height, greaterThanOrEqualTo(40), reason: 'not tiny');
    }

    standsOnIsland();
    // Between the menu and [Vistas] [Ajustes] (Vistas v3; «+» before), the
    // name of the profile after its dot.
    final islandRect = tester.getRect(island);
    expect(
      islandRect.left,
      greaterThan(
        tester.getRect(find.byKey(const ValueKey('chat-menu-button'))).right,
      ),
    );
    expect(
      islandRect.right,
      lessThan(
        tester.getRect(find.byKey(const ValueKey('chat-views-button'))).left,
      ),
    );
    expect(
      find.descendant(of: island, matching: find.text('Hermes')),
      findsOneWidget,
    );
    // the owner (gint72): no state dot of colour on the island.
    expect(
      find.descendant(
        of: island,
        matching: find.byKey(const ValueKey('island-dot-idle')),
      ),
      findsNothing,
    );
    final faceRect = tester.getRect(face);
    expect(faceRect.height, greaterThanOrEqualTo(40));
    expect(find.byType(ProfilePetAvatar), findsOneWidget);
    for (final scale in [1.3, 2.0]) {
      tester.platformDispatcher.textScaleFactorTestValue = scale;
      await tester.pump();
      expect(tester.getRect(face).size, faceRect.size);
      standsOnIsland();
      expect(tester.takeException(), isNull);
    }
    tester.platformDispatcher.clearTextScaleFactorTestValue();
    await tester.pump();
    expect(tester.takeException(), isNull);
    if (renderDir != null && renderDir.isNotEmpty) {
      final app = tester.state<HermesAppState>(find.byType(HermesApp));
      final initialTheme = app.themeId.value;
      for (final theme in [initialTheme, 'github']) {
        await app.setThemeId(theme);
        await tester.pump(); // Start AnimatedTheme before advancing its lerp.
        for (final scale in [1.0, 1.3, 2.0]) {
          tester.platformDispatcher.textScaleFactorTestValue = scale;
          await tester.pump(const Duration(seconds: 1));
          if (theme == 'github') {
            expect(
              Theme.of(tester.element(find.byType(ChatScreen))).brightness,
              Brightness.light,
            );
          }
          expect(tester.takeException(), isNull);
          await tester.runAsync(() async {
            final image = await captureImage(
              tester.element(find.byType(ChatScreen)),
            );
            final data = await image.toByteData(format: ui.ImageByteFormat.png);
            image.dispose();
            Directory(renderDir).createSync(recursive: true);
            File(
              '$renderDir/individual-pill-360-$theme-$scale.png',
            ).writeAsBytesSync(data!.buffer.asUint8List());
          });
        }
      }
    }
  });

  // The 1.2.15 QA 9600 bug: a new chat of the default profile drew the APP's
  // pet (the floating one) on its island instead of the profile's identity.
  // The earlier island tests never separated the two: they assigned no pet
  // at all and only checked that "a companion" stood on the island, so any
  // source passed. Here the two are different pets and each is changed alone.
  testWidgets("island sprite: the default profile's identity, never the "
      "app's pet; it follows the profile and ignores the app", (tester) async {
    tester.view.physicalSize = const Size(360, 800);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    mockCompanionStorage();
    await pumpChat(
      tester,
      connection: _remoteConn('island-identity'),
      messagesLoaded: true,
      initialPreferences: const {'companion.presence_level': 'full'},
    );
    final state = tester.state<HermesAppState>(find.byType(HermesApp));
    final profileControl = state.companion;
    final app = state.appCompanion;
    await _pumpUntilRealWork(
      tester,
      () => profileControl.isInitialized,
      real: const Duration(milliseconds: 10),
    );
    final (appPet, profilePet, laterPet) = (
      _islandPet('app-pet'),
      _islandPet('profile-pet'),
      _islandPet('later-pet'),
    );
    const connection = 'island-identity';
    addTearDown(ProfileIdentities.instance.reset);

    String drawn() {
      final island = find.byKey(const ValueKey('chat-pill-identity-slot'));
      final sheet = find.descendant(
        of: island,
        matching: find.byType(SpritesheetRenderer),
      );
      expect(sheet, findsOneWidget);
      final renderer = tester.widget<SpritesheetRenderer>(sheet);
      expect(renderer.animate, isFalse, reason: 'still in a chat');
      return renderer.companion.slug;
    }

    // The app's pet is A; the device record the app pet was migrated from
    // also says A; the profile's own stores say B.
    await tester.runAsync(() => app.select(appPet.slug));
    await tester.runAsync(() => profileControl.select(appPet.slug));
    ProfileIdentities.instance.publish(connection, 'default', profilePet);
    await tester.pump();
    await tester.pump();
    expect(drawn(), profilePet.slug);

    // Changing the app's pet leaves the island alone.
    await tester.runAsync(() => app.select(laterPet.slug));
    await tester.pump();
    expect(drawn(), profilePet.slug);

    // Changing the profile's identity changes it, with no restart.
    ProfileIdentities.instance.publish(connection, 'default', laterPet);
    await tester.pump();
    expect(drawn(), laterPet.slug);
  });

  testWidgets(
    'island sprite: a waiting turn leaves it at rest; the dot says it',
    (tester) async {
      mockCompanionStorage();
      final gateway = _UiRewindGateway();
      final chat = await pumpChat(
        tester,
        desktopGateway: gateway,
        connection: _remoteConn('chatpill-wait'),
