    ];
    final client = MockClient((request) async {
      requests.add(request.url);
      return http.Response(
        jsonEncode({
          'object': 'list',
          'session_id': 'sess-test',
          'messages': rows,
          if (paginate)
            'pagination': {
              'limit': 120,
              'offset': 0,
              'order': 'latest',
              'returned': 120,
            },
        }),
        200,
        headers: const {'content-type': 'application/json'},
      );
    });
    final api = testApiClient(
