  testWidgets('el control válido alcanza los RPC Desktop instrumentados', (
    tester,
  ) async {
    final temp = Directory.systemTemp.createTempSync(
      'chat-attachment-transport-control-',
    );
    addTearDown(() {
      if (temp.existsSync()) temp.deleteSync(recursive: true);
    });
    final file = File('${temp.path}/valido.pdf')
      ..writeAsBytesSync([0x25, 0x50, 0x44, 0x46, 1]);
    final attachment = AttachmentDraft(
      localId: 'valid-transport-control',
      type: AttachmentType.document,
      name: 'valido.pdf',
      mimeType: 'application/pdf',
      sizeBytes: file.lengthSync(),
      localPath: file.path,
    );
    secureStore[ChatDraftStore.keyForTesting(
      'conn-test',
      'sess-test',
      profile: 'default',
    )] = jsonEncode({
      'savedAt': DateTime.now().millisecondsSinceEpoch,
      'text': 'revisa',
      'attachments': [attachment.toJson()],
    });
    const pathProvider = MethodChannel('plugins.flutter.io/path_provider');
    TestWidgetsFlutterBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(pathProvider, (call) async => temp.path);
    addTearDown(
      () => TestWidgetsFlutterBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(pathProvider, null),
    );
    final gateway = _SubmissionGateway();

    final chat = await pumpChat(
      tester,
      connection: _remoteConn('conn-test'),
      desktopGateway: gateway,
      allowUnownedDesktopSnapshotForTesting: false,
      attachDesktopRuntimeOnLoad: false,
      initialPreferences: {
        'approval_global_mode': ApprovalMode.yolo.storageKey,
      },
    );
    for (
      var frame = 0;
      frame < 20 && find.byType(AttachmentCard).evaluate().isEmpty;
      frame++
    ) {
      await tester.pump(const Duration(milliseconds: 10));
    }
    final transportBeforeSend = (
      connect: gateway.connectCalls,
      resume: gateway.resumeCalls,
      imageAttach: gateway.imageAttachCalls,
      fileAttach: gateway.fileAttachCalls,
      submissions: gateway.submissions.length,
      outboxWrites: outboxWriteCalls,
    );
    expect(transportBeforeSend.resume, 0);
    await tester.tap(find.byKey(const ValueKey('send')));
    await _pumpUntilRealWork(
      tester,
      () => gateway.fileAttachCalls != 0 && gateway.submissions.isNotEmpty,
    );

    expect(gateway.connectCalls, transportBeforeSend.connect + 1);
    expect(gateway.resumeCalls, transportBeforeSend.resume + 1);
    expect(gateway.imageAttachCalls, transportBeforeSend.imageAttach);
    expect(gateway.fileAttachCalls, transportBeforeSend.fileAttach + 1);
    expect(gateway.submissions, hasLength(transportBeforeSend.submissions + 1));
    expect(outboxWriteCalls, greaterThan(transportBeforeSend.outboxWrites));
    expect(gateway.submissions.single, contains('@file:.hermes/valido.pdf'));
    expect(
      gateway.submissions.single,
      contains(AttachmentHistoryReference.markerPrefix),
    );
    expect(gateway.submissions.single, isNot(contains(temp.path)));
    expect(gateway.submissions.single, isNot(contains(file.path)));
    final optimisticUser = chat.messages.firstWhere(
      (message) => message['role'] == 'user',
    );
    expect(
      optimisticUser['content'],
      contains(AttachmentHistoryReference.markerPrefix),
    );
    expect(optimisticUser['content'], isNot(contains(temp.path)));
    final historicalFiles = Directory(
      '${temp.path}/${AttachmentUploader.sentAttachmentDirectoryName}',
    ).listSync().whereType<File>().toList();
    expect(historicalFiles, hasLength(1));
    expect(historicalFiles.single.readAsBytesSync(), file.readAsBytesSync());
    gateway.emitComplete();
    await tester.pump(const Duration(milliseconds: 50));
  });

  testWidgets('Bot Chat recupera foco y texto tras fallar y reintentar', (
    tester,
  ) async {
    final retry = Completer<List<Map<String, dynamic>>>();
    var loads = 0;
    var failing = true;
    final chat = await pumpChat(
      tester,
      connection: _remoteConn('conn-bot-composer-retry'),
      session: _session().copyWith(source: 'bot-mode'),
      missionBotProfile: const AgentProfile(name: 'Sol'),
      messagesLoaded: false,
      // conn-registry E3: the opening read and its four silent retries
      // (1/2/4/8 s, Desktop use-route-resume.ts:46-51) fail; then the card.
      storedMessageLoader: (_, _) {
        loads += 1;
        if (failing) throw StateError('initial load failed');
        return retry.future;
      },
    );
    await tester.pump();
    expect(find.text('No se pudieron cargar los mensajes'), findsNothing);
    for (var second = 0; second < 16; second++) {
      await tester.pump(const Duration(seconds: 1));
    }
    expect(find.text('No se pudieron cargar los mensajes'), findsOneWidget);
    failing = false;
    final loadsBeforeRetry = loads;
    await tester.tap(find.byIcon(Icons.refresh_rounded));
    await tester.pump();
    expect(loads, loadsBeforeRetry + 1);
    final composer = find.byType(TextField);
    expect(tester.widget<TextField>(composer).enabled, isTrue);
    await tester.tap(composer);
    await tester.pump();
    expect(tester.testTextInput.isVisible, isTrue);
    tester.testTextInput.enterText('Borrador mientras publica');
    await tester.pump();
    final send = find.byKey(const ValueKey('send'));
    final blockedSend = tester.widget<HermesTactileAction>(
      find.descendant(of: send, matching: find.byType(HermesTactileAction)),
    );
    expect(blockedSend.enabled, isFalse);
    await tester.tap(send);
    await tester.pump();
    expect(
      tester.widget<TextField>(composer).controller!.text,
      'Borrador mientras publica',
    );
    expect(
      chat.messages.where(
        (message) =>
            message['role'] == 'user' &&
            message['content'] == 'Borrador mientras publica',
      ),
      isEmpty,
    );
    retry.complete(const [
      {'role': 'user', 'content': 'Pregunta recuperada'},
      {'role': 'assistant', 'content': 'Respuesta recuperada'},
    ]);
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 100));
    expect(find.text('Respuesta recuperada'), findsOneWidget);
    expect(tester.widget<TextField>(composer).enabled, isTrue);
    await tester.tap(composer);
    await tester.pump();
    expect(tester.widget<TextField>(composer).focusNode!.hasFocus, isTrue);
    expect(tester.testTextInput.isVisible, isTrue);
    tester.testTextInput.enterText('Borrador tras reintentar');
    await tester.pump();
    expect(
      tester.widget<TextField>(composer).controller!.text,
      'Borrador tras reintentar',
    );
    expect(tester.takeException(), isNull);
  });

  testWidgets(
    'Bot Chat desbloquea composer al publicar tras dos fallos aunque resume siga pendiente',
    (tester) async {
      final retry = Completer<List<Map<String, dynamic>>>();
      final resume = Completer<DesktopSessionSnapshot>();
      final gateway = _UiRewindGateway()
        ..resumeExistingError = StateError('HTTP 401');
      var loads = 0;
      var failing = true;
      await pumpChat(
        tester,
        connection: _remoteConn('conn-bot-composer-published'),
        session: _session().copyWith(source: 'bot-mode'),
        missionBotProfile: const AgentProfile(name: 'Sol'),
        desktopGateway: gateway,
        messagesLoaded: false,
        storedMessageLoader: (_, _) {
          loads += 1;
          if (failing) throw StateError('HTTP 401');
          return retry.future;
        },
      );
      await tester.pump();
      // conn-registry E3: the opening read is retried in silence (1/2/4/8 s,
      // Desktop use-route-resume.ts:46-51) before the card shows.
      expect(find.text('No se pudieron cargar los mensajes'), findsNothing);
      for (var second = 0; second < 16; second++) {
        await tester.pump(const Duration(seconds: 1));
      }
      expect(find.text('No se pudieron cargar los mensajes'), findsOneWidget);
      final loadsAtCard = loads;
      await tester.tap(find.byIcon(Icons.refresh_rounded));
      await tester.pump();
      expect(loads, loadsAtCard + 1);
      expect(find.text('No se pudieron cargar los mensajes'), findsOneWidget);

      failing = false;
      gateway
        ..resumeExistingError = null
        ..resumeExistingGate = resume;
      await tester.tap(find.byIcon(Icons.refresh_rounded));
      await tester.pump();
      expect(loads, loadsAtCard + 2);
      final composer = find.byType(TextField);
      expect(tester.widget<TextField>(composer).enabled, isTrue);
      retry.complete(const [
        {'role': 'user', 'content': 'Pregunta tras recuperar backend'},
        {'role': 'assistant', 'content': 'Historial REST recuperado'},
      ]);
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 100));
      expect(gateway.resumeExistingCalls, greaterThanOrEqualTo(3));
      expect(resume.isCompleted, isFalse);
      expect(find.text('Historial REST recuperado'), findsOneWidget);
      expect(find.text('No se pudieron cargar los mensajes'), findsNothing);
      expect(tester.widget<TextField>(composer).enabled, isTrue);
      expect(find.byKey(const ValueKey('chat-refresh-progress')), findsNothing);
      await tester.tap(composer);
      await tester.pump();
      expect(tester.widget<TextField>(composer).focusNode!.hasFocus, isTrue);
      expect(tester.testTextInput.isVisible, isTrue);
      tester.testTextInput.enterText('Borrador con resume pendiente');
      await tester.pump();
      expect(
        tester.widget<TextField>(composer).controller!.text,
        'Borrador con resume pendiente',
      );
      resume.completeError(StateError('runtime sigue indisponible'));
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 100));
      expect(tester.widget<TextField>(composer).enabled, isTrue);
      expect(find.text('Historial REST recuperado'), findsOneWidget);
      expect(tester.takeException(), isNull);
    },
  );

