    expect(
      find.byKey(ValueKey(kVoiceModeEnabled ? 'voice' : 'send')),
      findsOneWidget,
    );
    if (kVoiceModeEnabled) {
      expect(find.byKey(const ValueKey('send')), findsNothing);
    }
    expect(tester.takeException(), isNull);
  });

