  group('plan limits (session.usage parity with Desktop)', () {
    setUp(AccountLimitsController.debugClearCache);

    Future<(ActiveChat, _AccountUsageGateway)> open(
      WidgetTester tester,
      String id, {
      String provider = 'provider-a',
      DashboardClient? dashboard,
    }) async {
      final gateway = _AccountUsageGateway();
      final chat = await pumpChat(
        tester,
        desktopGateway: gateway,
        connection: _remoteConn(id),
        messagesLoaded: false,
        transcriptDashboard: dashboard,
      );
      for (var frame = 0; !chat.hasDesktopRuntime && frame < 10; frame++) {
        await tester.pump(const Duration(milliseconds: 50));
      }
      expect(chat.hasDesktopRuntime, isTrue);
      gateway.emit('session.info', {
        'info': {'model': 'old-model', 'provider': provider},
      });
      await tester.pump();
      return (chat, gateway);
    }

    Future<void> openSheet(WidgetTester tester) async {
      await tester.tap(find.byKey(const ValueKey('status-pill-model')));
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 240));
      await tester.pump(const Duration(milliseconds: 50));
      // The plan limits close the sheet, after the list of models, which is
      // what scrolls (the rest stays pinned): bring the foot of the list in.
      final list = find.byKey(const ValueKey('model-picker-list'));
      if (list.evaluate().isNotEmpty) {
        final position = tester
            .state<ScrollableState>(
              find
                  .descendant(of: list, matching: find.byType(Scrollable))
                  .first,
            )
            .position;
        for (var i = 0; i < 3; i++) {
          position.jumpTo(position.maxScrollExtent);
          await tester.pump();
        }
      }
    }

    Future<void> closeSheet(WidgetTester tester) async {
      await tester.binding.handlePopRoute();
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 240));
    }

    testWidgets('opening the model sheet reads session.usage and shows it', (
      tester,
    ) async {
      final (chat, gateway) = await open(tester, 'conn-plan-limits');
      expect(gateway.usageCalls, isEmpty);
      expect(find.byKey(const ValueKey('status-pill-limit-dot')), findsNothing);
      await openSheet(tester);
      expect(gateway.usageCalls, [chat.desktopRuntimeSessionId]);
      expect(gateway.barsCalls, 0, reason: 'no Nous credits: no usage.bars');
      expect(find.text('Límites de tu plan'), findsOneWidget);
      // QA 9494: localized rows, never the server's English line.
      expect(find.text('Sesión actual'), findsOneWidget);
      expect(find.text('Quedan 72 %'), findsOneWidget);
      expect(find.text('Session: 72% remaining (28% used)'), findsNothing);
      await closeSheet(tester);
      // Weekly at 91 %: amber hint next to the model in the pill.
      expect(
        find.byKey(const ValueKey('status-pill-limit-dot')),
        findsOneWidget,
      );
      expect(tester.takeException(), isNull);
    });

    // Hermes >= 0.22.3: `session.usage` has no `account_lines`; the windows
    // come from `usage` in GET /api/model/options.
    DashboardClient catalogDashboard(
      List<Uri> reads, {
      int status = 200,
      Object? providers,
    }) => DashboardClient(
      host: '127.0.0.1',
      manualToken: 'dashboard-token',
      httpClientOverride: MockClient((request) async {
        reads.add(request.url);
        if (status != 200 || request.url.path != '/api/model/options') {
          return http.Response('{}', status == 200 ? 404 : status);
        }
        return http.Response(
          jsonEncode({
            'providers':
                providers ??
                [
                  {
                    'slug': 'openai-codex',
                    'name': 'OpenAI Codex',
                    'authenticated': true,
                    'usage': {
                      'windows': [
                        {
                          'label': 'Session',
                          'used_percent': 28.0,
                          'resets_at': null,
                          'scope': 'account',
                        },
                      ],
                    },
                  },
                ],
          }),
          200,
        );
      }),
    );

    testWidgets('without account_lines the session provider usage shows', (
      tester,
    ) async {
      final reads = <Uri>[];
      final (_, gateway) = await open(
        tester,
        'conn-plan-limits-catalog',
        provider: 'openai-codex',
        dashboard: catalogDashboard(reads),
      );
      gateway.usagePayload = acct.usage();
      await openSheet(tester);
      // Opening the chat now reads the server's busy-input policy too.
      // Keep the complete request sequence exact: the catalog is read once.
      expect(reads.map((u) => u.path), ['/api/config', '/api/model/options']);
      expect(find.text('Límites de tu plan'), findsOneWidget);
      expect(find.text('OpenAI Codex'), findsWidgets);
      expect(find.text('Sesión actual'), findsOneWidget);
      expect(find.text('Quedan 72 %'), findsOneWidget);
      expect(tester.takeException(), isNull);
    });

    testWidgets('with account_lines the catalog is not read', (tester) async {
      final reads = <Uri>[];
      final (_, gateway) = await open(
        tester,
        'conn-plan-limits-legacy',
        provider: 'openai-codex',
        dashboard: catalogDashboard(reads),
      );
      expect(gateway.usagePayload['account_lines'], isNotEmpty);
      await openSheet(tester);
      // Only the chat's busy-input config read: account_lines still avoids
      // every model-catalog request.
      expect(reads.map((u) => u.path), ['/api/config']);
      expect(find.text('Quedan 72 %'), findsOneWidget);
    });

    for (final status in const [404, 500]) {
      testWidgets('a catalog that fails ($status) leaves the block hidden', (
        tester,
      ) async {
        final reads = <Uri>[];
        final (_, gateway) = await open(
          tester,
          'conn-plan-limits-down-$status',
          provider: 'openai-codex',
          dashboard: catalogDashboard(reads, status: status),
        );
        gateway.usagePayload = acct.usage();
        await openSheet(tester);
        expect(reads, isNotEmpty);
        expect(find.text('Límites de tu plan'), findsNothing);
        expect(tester.takeException(), isNull);
      });
    }

    testWidgets('Nous credits also read usage.bars', (tester) async {
      final (_, gateway) = await open(tester, 'conn-plan-limits-nous');
      gateway
        ..usagePayload = acct.usage(credits: acct.nousLines)
        ..barsPayload = acct.barsAvailable;
      await openSheet(tester);
      expect(gateway.barsCalls, 1);
      expect(find.text(r'$3.00 de $20.00 disponibles'), findsOneWidget);
      await closeSheet(tester);
      expect(
        find.byKey(const ValueKey('status-pill-limit-dot')),
        findsOneWidget,
      );
    });

    testWidgets('a finished turn refreshes the limits', (tester) async {
      final (_, gateway) = await open(tester, 'conn-plan-limits-turn');
      await tester.enterText(find.byType(TextField), 'hola');
      await tester.pump(const Duration(milliseconds: 250));
      await tester.tap(find.byKey(const ValueKey('send')));
      await tester.pump(const Duration(milliseconds: 400));
      expect(gateway.usageCalls, isEmpty);
      gateway.emit('message.complete', const {'text': 'done'});
      await tester.pump(const Duration(milliseconds: 400));
      expect(gateway.usageCalls, hasLength(1));
      expect(
        find.byKey(const ValueKey('status-pill-limit-dot')),
        findsOneWidget,
      );
    });

    testWidgets('nothing is read while App Lock is locked', (tester) async {
      final (_, gateway) = await open(tester, 'conn-plan-limits-locked');
      await tester.enterText(find.byType(TextField), 'hola');
      await tester.pump(const Duration(milliseconds: 250));
      await tester.tap(find.byKey(const ValueKey('send')));
      await tester.pump(const Duration(milliseconds: 400));
      expect(gateway.submissions, hasLength(1));
      final lock = tester
          .state<HermesAppState>(find.byType(HermesApp))
          .appLock
          .locked;
      lock.value = true;
      addTearDown(() => lock.value = false);
      // The turn finishes behind the lock: no read of the plan limits.
      gateway.emit('message.complete', const {'text': 'done'});
      await tester.pump(const Duration(milliseconds: 400));
      expect(gateway.usageCalls, isEmpty);
      expect(find.byKey(const ValueKey('status-pill-limit-dot')), findsNothing);
      expect(tester.takeException(), isNull);
    });
  });

