  testWidgets(
    'desmontar la pantalla descarta la confirmación exacta y libera release',
    (tester) async {
      final gateway = _ModelConfigGateway()..modelConfirmRequired = true;
      var successorTapped = false;
      final chat = await pumpChat(
        tester,
        desktopGateway: gateway,
        connection: _remoteConn('conn-model-confirm-unmount'),
        messagesLoaded: false,
        attachDesktopRuntimeOnLoad: false,
        allowUnownedDesktopSnapshotForTesting: false,
        turnIdempotencyCapability: () async => true,
        storedMessageLoader: (_, _) async => const [
          {
            'message_id': 'ui-user',
            'role': 'user',
            'content': 'prime release ownership',
          },
          {
            'message_id': 'ui-assistant',
            'role': 'assistant',
            'content': 'ownership accepted',
          },
        ],
      );
      chat.markStoredSessionMissing();
      await _primeUiReleaseOwnership(tester, chat, gateway);
      gateway.emit('session.info', const {
        'info': {'model': 'old-model', 'provider': 'provider-a'},
      });
      await tester.pump();

      await tester.tap(find.byKey(const ValueKey('status-pill-model')));
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 240));
      await tester.pump(const Duration(milliseconds: 50));
      await tapModelRow(tester, 'new-model');
      await tester.pump();

      final pending = chat.pendingSessionConfigChange(
        DesktopSessionConfigKey.model,
      )!;
      expect(find.text('Confirm expensive model'), findsOneWidget);
      expect(pending.status, SessionConfigChangeStatus.confirmRequired);
      expect(chat.canReleaseToDesktop, isFalse);

      final keepAlive = chat.changes.listen((_) {});
      addTearDown(keepAlive.cancel);
      final screenContext = tester.element(find.byType(ChatScreen));
      final screenRoute = ModalRoute.of(screenContext)!;
      final navigator = Navigator.of(screenContext);
      unawaited(
        navigator.push<void>(
          DialogRoute<void>(
            context: screenContext,
            builder: (_) => AlertDialog(
              key: const ValueKey('model-confirm-successor'),
              actions: [
                TextButton(
                  key: const ValueKey('model-confirm-successor-action'),
                  onPressed: () => successorTapped = true,
                  child: const Text('Successor action'),
                ),
              ],
            ),
          ),
        ),
      );
      await tester.pump();
      expect(find.text('Confirm expensive model'), findsOneWidget);

      navigator.removeRoute(screenRoute);
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 300));

      expect(find.byType(ChatScreen), findsNothing);
      // A detached dialog may still animate out, but it cannot become current.
      final detached = find.text('Confirm expensive model');
      if (detached.evaluate().isNotEmpty) {
        expect(
          ModalRoute.of(tester.element(detached.first))?.isCurrent,
          isFalse,
        );
      }
      await tester.tap(
        find.byKey(const ValueKey('model-confirm-successor-action')),
      );
      await tester.pump();
      expect(successorTapped, isTrue);

      final dismissed = chat.pendingSessionConfigChange(
        DesktopSessionConfigKey.model,
      )!;
      expect(dismissed.requestEpoch, pending.requestEpoch);
      expect(dismissed.status, SessionConfigChangeStatus.superseded);
      expect(gateway.modelConfirmationFlags, [false]);
      expect(chat.effectiveSessionConfig.model, 'old-model');
      expect(chat.canReleaseToDesktop, isTrue);
      expect(tester.takeException(), isNull);
    },
  );

  testWidgets(
    'desmontar una pantalla vieja no descarta una confirmación más nueva',
    (tester) async {
      final gateway = _ModelConfigGateway()..modelConfirmRequired = true;
      final chat = await pumpChat(
        tester,
        desktopGateway: gateway,
        connection: _remoteConn('conn-model-confirm-stale-unmount'),
        messagesLoaded: false,
        attachDesktopRuntimeOnLoad: false,
        allowUnownedDesktopSnapshotForTesting: false,
        turnIdempotencyCapability: () async => true,
        storedMessageLoader: (_, _) async => const [
          {
            'message_id': 'ui-user',
            'role': 'user',
            'content': 'prime release ownership',
          },
          {
            'message_id': 'ui-assistant',
            'role': 'assistant',
            'content': 'ownership accepted',
          },
        ],
      );
      chat.markStoredSessionMissing();
      await _primeUiReleaseOwnership(tester, chat, gateway);

      await tester.tap(find.byKey(const ValueKey('status-pill-model')));
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 240));
      await tester.pump(const Duration(milliseconds: 50));
      await tapModelRow(tester, 'new-model');
      await tester.pump();
      final stale = chat.pendingSessionConfigChange(
        DesktopSessionConfigKey.model,
      )!;

      final current = await chat.setSessionModel(
        DesktopModelSelection(modelId: 'bad-model', providerSlug: 'provider-a'),
      );
      expect(current.requestEpoch, isNot(stale.requestEpoch));
      expect(current.status, SessionConfigChangeStatus.confirmRequired);

      final keepAlive = chat.changes.listen((_) {});
      addTearDown(keepAlive.cancel);
      final screenContext = tester.element(find.byType(ChatScreen));
      final screenRoute = ModalRoute.of(screenContext)!;
      final navigator = Navigator.of(screenContext);
      unawaited(
        navigator.push<void>(
          DialogRoute<void>(
            context: screenContext,
            builder: (dialogContext) => AlertDialog(
              key: const ValueKey('newer-unrelated-dialog'),
              title: const Text('Newer unrelated dialog'),
              actions: [
                TextButton(
                  key: const ValueKey('close-newer-unrelated-dialog'),
                  onPressed: () => Navigator.pop(dialogContext),
                  child: const Text('Close newer dialog'),
                ),
              ],
            ),
          ),
        ),
      );
      await tester.pump();
      expect(
        find.byKey(const ValueKey('newer-unrelated-dialog')),
        findsOneWidget,
      );

      navigator.removeRoute(screenRoute);
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 300));

      expect(find.byType(ChatScreen), findsNothing);
      // The old screen removes only the dialog it opened (the stale
      // confirmation, answered with null: nothing is confirmed). Routes
      // under a top route that is still pushing are removed on the frame
      // after the screen goes, so wait one frame before looking: whether the
      // dialog is still painted right after teardown is a matter of frames,
      // not of behaviour (same event order with or without the sheet's second
      // page: push, removal of the owned route, answer null).
      await tester.pump();
      expect(find.text('Confirm expensive model'), findsNothing);
      // What the teardown must not touch: the newer unrelated dialog on top
      // and, below, the chat's newer confirmation (checked at the end).
      expect(
        find.byKey(const ValueKey('newer-unrelated-dialog')),
        findsOneWidget,
      );
      await tester.tap(
        find.byKey(const ValueKey('close-newer-unrelated-dialog')),
      );
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 300));
      expect(
        find.byKey(const ValueKey('newer-unrelated-dialog')),
        findsNothing,
      );

      final retained = chat.pendingSessionConfigChange(
        DesktopSessionConfigKey.model,
      )!;
      expect(retained.requestEpoch, current.requestEpoch);
      expect(retained.status, SessionConfigChangeStatus.confirmRequired);
      expect(chat.canReleaseToDesktop, isFalse);
      expect(gateway.modelConfirmationFlags, [false, false]);
      expect(tester.takeException(), isNull);

      expect(chat.dismissSessionConfigConfirmation(current), isTrue);
      expect(chat.canReleaseToDesktop, isTrue);
    },
  );

  group('md1215 cambio de modelo en el chat', () {
    Future<(ActiveChat, _ModelConfigGateway)> pumpModelChat(
      WidgetTester tester,
      String connectionId, {
      _ModelConfigGateway? gateway,
    }) async {
      final fake = gateway ?? _ModelConfigGateway();
      final chat = await pumpChat(
        tester,
        desktopGateway: fake,
        connection: _remoteConn(connectionId),
        messagesLoaded: false,
      );
      for (var frame = 0; !chat.hasDesktopRuntime && frame < 10; frame++) {
        await tester.pump(const Duration(milliseconds: 240));
      }
      expect(chat.hasDesktopRuntime, isTrue);
      return (chat, fake);
    }

    Future<void> openModelSheet(WidgetTester tester) async {
      await tester.tap(find.byKey(const ValueKey('status-pill-model')));
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 240));
      await tester.pump(const Duration(milliseconds: 50));
      expect(find.byKey(const ValueKey('chat-model-dialog')), findsOneWidget);
    }

    Future<void> closeModelSheet(WidgetTester tester) async {
      await tester.binding.handlePopRoute();
      await tester.pump();
      // pm1215: the sheet shrinks back into the pill (kPillMorphClose).
      await tester.pump(const Duration(milliseconds: 300));
      expect(find.byKey(const ValueKey('chat-model-dialog')), findsNothing);
    }

    Future<void> waitForModelSheetToClose(WidgetTester tester) async {
      for (
        var frame = 0;
        find.byKey(const ValueKey('chat-model-dialog')).evaluate().isNotEmpty &&
            frame < 10;
        frame++
      ) {
        await tester.pump(const Duration(milliseconds: 100));
      }
      expect(find.byKey(const ValueKey('chat-model-dialog')), findsNothing);
    }

    for (final saved in [true, false]) {
      testWidgets(
        'review M1: effective provider and capabilities follow ${saved ? 'saved cross-provider draft' : 'catalog default'}',
        (tester) async {
          final semantics = tester.ensureSemantics();
          const connectionId = 'conn-sheet-provider-review';
          const sessionId = 'mob-sheet-provider-review';
          const scope = '${connectionId}_default_$sessionId';
          final gateway = _SessionlessCatalogGateway()
            ..catalogOverride = DesktopModelCatalog.fromJson(const {
              'model': 'disk-model',
              'provider': 'provider-a',
              'providers': [
                {
                  'slug': 'provider-a', 'name': 'Proveedor A',
                  'authenticated': true, 'is_current': true,
                  // The saved id also exists on A: marking A would look plausible.
                  'models': ['disk-model', 'shared-model'],
                  'capabilities': {
                    'disk-model': {'reasoning': false, 'fast': false},
                    'shared-model': {'reasoning': true, 'fast': true},
                  },
                },
                {
                  'slug': 'provider-b',
                  'name': 'Proveedor B',
                  'authenticated': true,
                  'models': ['shared-model'],
                  'capabilities': {
                    'shared-model': {'reasoning': false, 'fast': false},
                  },
                },
              ],
            });
          final chat = await pumpChat(
            tester,
            desktopGateway: gateway,
            connection: _remoteConn(connectionId),
            session: const Session(
              id: sessionId,
              title: 'Nuevo chat',
              model: 'hermes-agent',
              source: 'mobile',
              messageCount: 0,
              isActive: true,
              preview: '',
              profile: 'default',
              startedAt: 1,
            ),
            attachDesktopRuntimeOnLoad: false,
            initialPreferences: {
              if (saved) 'selected_model_$scope': 'shared-model',
              if (saved) 'selected_provider_$scope': 'provider-b',
              'selected_reasoning_$scope': 'high',
              'selected_fast_$scope': 'fast',
            },
          );
          await openModelSheet(tester);
          final model = saved ? 'shared-model' : 'disk-model';
          final provider = saved ? 'provider-b' : 'provider-a';
          expect(chat.hasDesktopRuntime, isFalse);
          expect(chosenModelsInSheet(tester), contains(model));
          expect(
            chosenModelsInSheet(tester),
            contains(saved ? 'Proveedor B' : 'Proveedor A'),
          );
          final pill = tester.widget<ChatStatusPill>(
            find.byKey(const ValueKey('chat-status-pill')),
          );
          expect((pill.modelLeading as ProviderLogo).provider, provider);
          expect(pill.modelDetail, isNull);
          for (final key in ['msv-tile-think', 'session-fast-switch']) {
            expect(
              tester
                  .getSemantics(find.byKey(ValueKey(key)))
                  .flagsCollection
                  .isEnabled,
              ui.Tristate.isFalse,
            );
          }
          final limits = tester.widget<AccountLimitsSection>(
            find.byType(AccountLimitsSection),
          );
          expect(limits.preferredProvider, provider);
          await openAllModels(tester);
          final selected = find.byKey(ValueKey('model-card-$provider-$model'));
          expect(selected, findsOne);
          final selection = find.descendant(
            of: selected,
            matching: find.bySemanticsLabel(RegExp('^${RegExp.escape(model)}')),
          );
          expect(
            tester.getSemantics(selection).flagsCollection.isSelected,
            ui.Tristate.isTrue,
          );
          await closeModelSheet(tester);
          semantics.dispose();
          expect(tester.takeException(), isNull);
        },
      );
    }

    testWidgets(
      'model sheet follows an existing session and live config updates',
      (tester) async {
        final (_, gateway) = await pumpModelChat(tester, 'conn-sheet-live');
        gateway.emit('session.info', const {
          'info': {'model': 'old-model', 'provider': 'provider-a'},
        });
        await tester.pump();
        await openModelSheet(tester);
        expect(chosenModelsInSheet(tester), contains('old-model'));
        gateway.emit('session.info', const {
          'info': {'model': 'new-model', 'provider': 'provider-a'},
        });
        await tester.pump();
        expect(chosenModelsInSheet(tester), contains('new-model'));
        expect(chosenModelsInSheet(tester), isNot(contains('old-model')));
        expect(tester.takeException(), isNull);
        await closeModelSheet(tester);
      },
    );

    for (final delayed in [false, true]) {
      testWidgets(
        'model sheet: new chat resolves profile default${delayed ? ' after loading' : ''}, then explicit pick',
        (tester) async {
          final semantics = tester.ensureSemantics();
          final gate = delayed ? Completer<void>() : null;
          final gateway = _SessionlessCatalogGateway()..catalogGate = gate;
          final chat = await pumpChat(
            tester,
            desktopGateway: gateway,
            connection: _remoteConn('conn-sheet-default-$delayed'),
            session: const Session(
              id: 'mob-sheet-default',
              title: 'Nuevo chat',
              model: 'hermes-agent',
              source: 'mobile',
              messageCount: 0,
              isActive: true,
              preview: '',
              profile: 'default',
              startedAt: 1,
            ),
            attachDesktopRuntimeOnLoad: false,
          );
          expect(chat.hasDesktopRuntime, isFalse);
          await openModelSheet(tester);
          if (gate != null) {
            expect(chosenModelsInSheet(tester), contains('Cargando modelo…'));
            expect(find.text('?'), findsNothing);
            gate.complete();
            for (var i = 0; i < 8; i++) {
              await tester.pump(const Duration(milliseconds: 50));
            }
          }
          expect(chosenModelsInSheet(tester), contains('disk-model'));
          expect(chosenModelsInSheet(tester), contains('Proveedor A'));
          final pill = find.byKey(const ValueKey('status-pill-model'));
          expect(
            find.descendant(of: pill, matching: find.text('disk-model')),
            findsOne,
          );
          await openAllModels(tester);
          final current = find.byKey(
            const ValueKey('model-card-provider-a-disk-model'),
          );
          expect(
            tester
                .getSemantics(
                  find.descendant(
                    of: current,
                    matching: find.bySemanticsLabel(RegExp(r'^disk-model\.')),
                  ),
                )
                .flagsCollection
                .isSelected,
            ui.Tristate.isTrue,
          );
          await tapModelRow(tester, 'other-model');
          await tester.pump();
          await waitForModelSheetToClose(tester);
          expect(chat.hasDesktopRuntime, isFalse);
          await openModelSheet(tester);
          expect(chosenModelsInSheet(tester), contains('other-model'));
          expect(
            find.descendant(of: pill, matching: find.text('other-model')),
            findsOne,
          );
          expect(tester.takeException(), isNull);
          await closeModelSheet(tester);
          semantics.dispose();
        },
      );
    }

    testWidgets(
      'model selection applies a supported preset to the live session',
      (tester) async {
        const connectionId = 'conn-model-preset-live';
        final gateway = _ModelConfigGateway()
          ..catalogOverride = DesktopModelCatalog.fromJson(const {
            'model': 'old-model',
            'provider': 'provider-a',
            'providers': [
              {
                'slug': 'provider-a',
                'name': 'Provider A',
                'is_current': true,
                'models': ['old-model', 'new-model'],
                'capabilities': {
                  'old-model': {'reasoning': true, 'fast': true},
                  'new-model': {'reasoning': true, 'fast': true},
                },
              },
            ],
          });
        final chat = await pumpChat(
          tester,
          desktopGateway: gateway,
          connection: _remoteConn(connectionId),
          messagesLoaded: false,
          initialPreferences: {
            'model_presets_v1.$connectionId': jsonEncode({
              'provider-a::new-model': {'effort': 'high', 'fast': 'fast'},
            }),
          },
        );
        for (var frame = 0; !chat.hasDesktopRuntime && frame < 10; frame++) {
          await tester.pump(const Duration(milliseconds: 240));
        }
        gateway.emit('session.info', const {
          'info': {'model': 'old-model', 'provider': 'provider-a'},
        });
        await tester.pump();

        await openModelSheet(tester);
        await tapModelRow(tester, 'new-model');
        await tester.pump();
        await waitForModelSheetToClose(tester);

        expect(gateway.reasoningSelections, [DesktopReasoningEffort.high]);
        expect(gateway.fastSelections, [DesktopFastMode.fast]);
        expect(tester.takeException(), isNull);
      },
    );

    testWidgets(
      'sessionless model selection stages its preset without config writes',
      (tester) async {
        const connectionId = 'conn-model-preset-draft';
        final gateway = _SessionlessCatalogGateway()
          ..resumeExistingError = const TuiGatewayRpcError(
            'session.resume',
            'not found',
            code: 4007,
          );
        final chat = await pumpChat(
          tester,
          desktopGateway: gateway,
          connection: _remoteConn(connectionId),
          attachDesktopRuntimeOnLoad: false,
          initialPreferences: {
            'model_presets_v1.$connectionId': jsonEncode({
              'provider-a::other-model': {'effort': 'high', 'fast': 'fast'},
            }),
          },
        );
        expect(chat.hasDesktopRuntime, isFalse);

        await openModelSheet(tester);
        await tapModelRow(tester, 'other-model');
        await tester.pump();
        await waitForModelSheetToClose(tester);
        expect(chat.hasDesktopRuntime, isFalse);

        expect(gateway, isNot(isA<HermesDesktopSessionConfigGateway>()));
        final config = chat.stagedFirstSubmitConfigForTesting;
        expect(config.model?.modelId, 'other-model');
        expect(config.reasoningEffort, DesktopReasoningEffort.high);
        expect(config.fastMode, DesktopFastMode.fast);
        expect(tester.takeException(), isNull);
      },
    );

    testWidgets('a rejected reasoning write keeps the previous preset', (
      tester,
    ) async {
      const connectionId = 'conn-model-preset-rollback';
      final gateway = _ModelConfigGateway()
        ..catalogOverride = DesktopModelCatalog.fromJson(const {
          'model': 'old-model',
          'provider': 'provider-a',
          'providers': [
            {
              'slug': 'provider-a',
              'name': 'Provider A',
              'is_current': true,
              'models': ['old-model'],
              'capabilities': {
                'old-model': {'reasoning': true, 'fast': true},
              },
            },
          ],
        })
        ..reasoningError = const TuiGatewayRpcError(
          'config.set',
          'rejected',
          code: 5001,
        );
      final chat = await pumpChat(
        tester,
        desktopGateway: gateway,
        connection: _remoteConn(connectionId),
        messagesLoaded: false,
        initialPreferences: {
          'selected_model_${connectionId}_default_sess-test': 'old-model',
          'selected_provider_${connectionId}_default_sess-test': 'provider-a',
          'model_presets_v1.$connectionId': jsonEncode({
            'provider-a::old-model': {'effort': 'low'},
          }),
        },
      );
      for (var frame = 0; !chat.hasDesktopRuntime && frame < 10; frame++) {
        await tester.pump(const Duration(milliseconds: 240));
      }
      gateway.emit('session.info', const {
        'info': {'model': 'old-model', 'provider': 'provider-a'},
      });
      await tester.pump();

      await openModelSheet(tester);
      // The slider's «Alto» step is the fifth of eight.
      final trackFinder = find.byKey(
        const ValueKey('model-picker-reasoning-track'),
      );
      await tester.ensureVisible(trackFinder);
      await tester.pump();
      final track = tester.getRect(trackFinder);
      await tester.tapAt(
        Offset(
          track.left +
              kReasoningTrackInset +
              (track.width - 2 * kReasoningTrackInset) * 4 / 7,
          track.center.dy,
        ),
      );
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 300));

      final prefs = await SharedPreferences.getInstance();
      final preset = ModelPresetsStore(
        prefs,
        connectionId: connectionId,
      ).read('provider-a', 'old-model');
      expect(gateway.reasoningSelections, [DesktopReasoningEffort.high]);
      expect(preset?.effort, DesktopReasoningEffort.low);
      expect(tester.takeException(), isNull);
      await closeModelSheet(tester);
    });

