  testWidgets(
    'auth Dashboard muestra banner sin tapar historial o snackbar y se limpia',
    (tester) async {
      final gateway = _AuthLinkGateway()
        ..connected = false
        ..connectError = const DashboardAuthException(
          DashboardAuthFailureCode.loginRequired,
        );
      addTearDown(gateway.close);
      final chat = await pumpChat(
        tester,
        desktopGateway: gateway,
        connection: _remoteConn('conn-auth-banner'),
        messages: const [
          {'role': 'assistant', 'content': 'Respuesta REST conservada'},
          {
            'role': 'user',
            'content': 'pregunta REST conservada',
            '_desktopRowId': 73,
          },
        ],
      );
      await tester.pump(const Duration(milliseconds: 200));

      final banner = find.byKey(const ValueKey('chat-dashboard-auth-required'));
      expect(banner, findsOneWidget);
      expect(find.textContaining('Respuesta REST conservada'), findsOneWidget);
      expect(find.textContaining('pregunta REST conservada'), findsOneWidget);
      // The island says it in one line; the whole text is what the screen
      // reader hears (a polite live region).
      expect(
        find.descendant(of: banner, matching: find.text('Inicia sesión')),
        findsOneWidget,
      );
      expect(
        find.descendant(
          of: banner,
          matching: find.byWidgetPredicate(
            (w) =>
                w is Semantics &&
                w.properties.liveRegion == true &&
                (w.properties.label ?? '').startsWith(
                  'Inicia sesión. Inicia sesión en el Dashboard para '
                  'reconectar el chat en vivo. Tu historial sigue disponible.',
                ),
          ),
        ),
        findsOneWidget,
      );
      expect(find.textContaining('DashboardAuthException'), findsNothing);

      await tester.tap(find.byIcon(Icons.edit_outlined));
      await tester.pumpAndSettle();
      await tester.enterText(
        find.byKey(const ValueKey('inline-message-editor-field')),
        'texto que no se enviará',
      );
      await tester.pump();
      await tester.tap(
        find.byKey(const ValueKey('inline-message-editor-save')),
      );
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 700));

      // One at a time: the notice of what just happened is said first, the
      // sign-in line waits behind it and comes back.
      expect(find.byType(HermesNoticeCard), findsOneWidget);
      expect(
        find.descendant(
          of: find.byKey(const ValueKey('island')),
          matching: find.byType(HermesNoticeCard),
        ),
        findsOneWidget,
      );
      expect(banner, findsNothing);
      expect(find.byKey(const ValueKey('island-waiting')), findsOneWidget);
      expect(find.textContaining('pregunta REST conservada'), findsOneWidget);

      gateway.connectError = null;
      tester.binding.handleAppLifecycleStateChanged(AppLifecycleState.inactive);
      tester.binding.handleAppLifecycleStateChanged(AppLifecycleState.resumed);
      await tester.pump();
      await tester.pump();

      for (var frame = 0; frame < 20 && chat.dashboardAuthRequired; frame++) {
        await tester.pump(const Duration(milliseconds: 50));
      }
      expect(gateway.isConnected, isTrue);
      expect(gateway.successfulDials, 1, reason: 'the lifecycle owner dials once');
      expect(chat.dashboardAuthRequired, isFalse);
      expect(banner, findsNothing);
      expect(find.byType(HermesNoticeCard), findsOneWidget);
      expect(find.textContaining('Respuesta REST conservada'), findsOneWidget);
      expect(tester.takeException(), isNull);
    },
  );

  testWidgets(
    'banner de auth Dashboard se cierra y reaparece cuando vuelve a exigirse',
    (tester) async {
      final gateway = _UiRewindGateway()
        ..connected = false
        ..connectError = const DashboardAuthException(
          DashboardAuthFailureCode.loginRequired,
        );
      final chat = await pumpChat(
        tester,
        desktopGateway: gateway,
        connection: _remoteConn('conn-auth-banner-dismiss'),
        messages: const [
          {'role': 'assistant', 'content': 'Respuesta REST conservada'},
        ],
      );
      await tester.pump(const Duration(milliseconds: 200));

      final banner = find.byKey(const ValueKey('chat-dashboard-auth-required'));
      expect(banner, findsOneWidget);
      // Sin X: se retira deslizándolo hacia arriba.
      await _dismissIslandEvent(tester);
      expect(banner, findsNothing);
      expect(chat.dashboardAuthRequired, isTrue);
      expect(find.textContaining('Respuesta REST conservada'), findsOneWidget);

      // Un warm-up correcto limpia la exigencia; otro que vuelve a pedir
      // sesión es una ocurrencia nueva del aviso.
      gateway.connectError = null;
      await chat.warmDesktopGateway();
      await tester.pump();
      expect(chat.dashboardAuthRequired, isFalse);
      expect(banner, findsNothing);

      gateway
        ..connected = false
        ..connectError = const DashboardAuthException(
          DashboardAuthFailureCode.loginRequired,
        );
      await chat.warmDesktopGateway();
      await tester.pump();
      // The island takes it up on the next frame (measured in a
      // gate run: 0 on this frame, 1 on the next; why it now takes that frame
      // is not pinned down).
      await tester.pump();
      expect(chat.dashboardAuthRequired, isTrue);
      expect(banner, findsOneWidget);
      await tester.pump(const Duration(seconds: 5));
      expect(tester.takeException(), isNull);
    },
  );

