  testWidgets(
    'guardar edición sigue siendo táctil con teclado Android compacto',
    (tester) async {
      // 28 dp taller than the smallest phone it used to be drawn on: what
      // the island's sprite takes at the top of the chat.
      tester.view
        ..physicalSize = const Size(320, 668)
        ..devicePixelRatio = 1
        ..viewInsets = const FakeViewPadding(bottom: 300);
      addTearDown(tester.view.reset);
      final gateway = _UiRewindGateway();
      final chat = await pumpChat(
        tester,
        desktopGateway: gateway,
        connection: _remoteConn('conn-compact-rewrite'),
        messages: [
          {'role': 'assistant', 'content': 'Respuesta original'},
          {'role': 'user', 'content': 'pregunta original'},
        ],
      );

      // The notch slot takes 40 dp more of this tiny transcript: the edit
      // action starts just above the viewport and is scrolled into reach.
      final edit = find.byIcon(Icons.edit_outlined, skipOffstage: false);
      await tester.ensureVisible(edit);
      await tester.pumpAndSettle();
      expect(edit.hitTestable(), findsOneWidget);
      await tester.tap(edit);
      await tester.pumpAndSettle();
      await tester.enterText(
        find.byKey(const ValueKey('inline-message-editor-field')),
        'pregunta corregida desde Android',
      );
      await tester.pump();
      // El campo es de una línea: el asa del caret cae sobre el pie; se suelta
      // el foco para comprobar que ↑ es pulsable.
      FocusManager.instance.primaryFocus?.unfocus();
      await tester.pump();
      // Typing brings the caret into view with Flutter's own 100 ms scroll
      // (editable_text.dart, _scheduleShowCaretOnScreen(withAnimation:
      // true)), and while a driven scroll runs the list ignores touches
      // (scroll_activity.dart, DrivenScrollActivity.shouldIgnorePointer;
      // scrollable.dart, IgnorePointer(ignoring: _shouldIgnorePointer)).
      // Measured: taken with no time elapsed, the hit
      // test at save's centre stopped at the list's own gesture listener.
      // A finger lands after that scroll: wait it out, then judge where save
      // ended up.
      await tester.pump(const Duration(milliseconds: 150));

      final apply = find.byKey(const ValueKey('inline-message-editor-save'));
      expect(apply, findsOneWidget);
      // Between the header and the foot the list keeps clear of: never
      // under the composer, the notch or the arrow.
      final list = tester.widget<ListView>(chatListFinder());
      final listRect = tester.getRect(chatListFinder());
      final reserved = list.padding! as EdgeInsets;
      final save = tester.getRect(apply);
      expect(
        save.bottom,
        lessThanOrEqualTo(listRect.bottom - reserved.bottom + 0.5),
      );
      expect(save.top, greaterThanOrEqualTo(listRect.top + reserved.top - 0.5));
      expect(apply.hitTestable(), findsOneWidget);
      await tester.tap(apply);
      await tester.pump(const Duration(milliseconds: 700));

      expect(gateway.rewinds, [
        (text: 'pregunta corregida desde Android', ordinal: 0),
      ]);
      tester.view.viewInsets = const FakeViewPadding();
      await tester.pump();
      gateway.emit('message.complete', {'text': 'Respuesta corregida Android'});
      for (var frame = 0; frame < 60 && chat.isStreaming; frame++) {
        await tester.pump(const Duration(milliseconds: 33));
      }
      // fh1215: with the keyboard gone the taller transcript (no app bar
      // band) fits whole; the list settles back from the editor's offset.
      await tester.pump(const Duration(milliseconds: 400));
      await tester.pump(const Duration(milliseconds: 400));
      expect(find.text('Respuesta corregida Android'), findsOneWidget);
      expect(chat.isStreaming, isFalse);
      expect(tester.takeException(), isNull);
    },
  );

  Finder transcript(String text) => find.descendant(
    of: chatListFinder(),
    matching: find.textContaining(text),
  );

  Future<({ActiveChat chat, _UiRewindGateway gateway})> openRewriteEditor(
    WidgetTester tester,
    String connectionId, {
    _UiRewindGateway? gateway,
    StoredSessionMessageLoader? storedMessageLoader,
  }) async {
    gateway ??= _UiRewindGateway();
    final chat = await pumpChat(
      tester,
      desktopGateway: gateway,
      connection: _remoteConn(connectionId),
      storedMessageLoader: storedMessageLoader,
      messages: const [
        {'role': 'assistant', 'content': 'Respuesta original'},
        {'role': 'user', 'content': 'pregunta original'},
      ],
    );
    await tester.tap(find.byIcon(Icons.edit_outlined));
    await tester.pumpAndSettle();
    return (chat: chat, gateway: gateway);
  }

  Future<void> submitEdit(WidgetTester tester, [String? text]) async {
    if (text != null) {
      await tester.enterText(
        find.byKey(const ValueKey('inline-message-editor-field')),
        text,
      );
      await tester.pump();
    }
    await tester.tap(find.byKey(const ValueKey('inline-message-editor-save')));
  }

