  testWidgets(
    'status loop reúne control proceso y tareas en una sola actividad',
    (tester) async {
      final gateway = _StableRefreshGateway(subagents: const [])
        ..processSnapshot = const AgentCenterSnapshot(
          snapshots: [],
          processes: [
            BackgroundProcessEntry(
              opaqueId: 'process-mixed',
              status: AgentCenterStatus.running,
              uptimeSeconds: 8,
              command: 'python worker.py',
            ),
          ],
        );
      final chat = await pumpChat(
        tester,
        connection: _remoteConn('background-mixed-status'),
        desktopGateway: gateway,
        messages: const [
          {'role': 'user', 'content': 'PUBLIC_MIXED_REQUEST'},
        ],
      );
      expect(
        await chat.send(
          fullText: 'PUBLIC_MIXED_PARENT_REQUEST',
          model: 'hermes-agent',
          history: chat.messages,
        ),
        isTrue,
      );
      gateway.emit('message.start');
      gateway.emit('message.complete', const {'text': 'PUBLIC_MIXED_DONE'});
      await tester.pump();
      gateway.controlSnapshot = SessionControlSnapshot(
        goal: const SessionGoalSnapshot(
          title: 'PUBLIC_STANDING_GOAL',
          status: 'waiting',
          turnsUsed: 2,
          maxTurns: 8,
        ),
        loop: SessionLoopSnapshot(
          status: 'paused',
          interval: const Duration(minutes: 5),
          lastRunAt: DateTime.utc(2026, 9, 21, 10),
          nextDueAt: DateTime.utc(2026, 9, 21, 10, 5),
          ticksFired: 3,
          awaitingResponse: true,
          deferredByGoal: true,
        ),
        heartbeat: SessionHeartbeatSnapshot(
          status: 'active',
          interval: const Duration(minutes: 10),
          lastRunAt: DateTime.utc(2026, 9, 21, 10),
          nextDueAt: DateTime.utc(2026, 9, 21, 10, 10),
          fireCount: 4,
        ),
        revision: 'mixed-1',
        updatedAt: DateTime.utc(2026, 9, 21, 10),
      );
      gateway.emit('todo.updated', const {
        'revision': 1,
        'todos': [
          {
            'id': 'task-mixed',
            'content': 'PUBLIC_PENDING_TASK',
            'status': 'in_progress',
          },
        ],
      });
      final readsBeforeLoopStatus = gateway.controlReadCalls;
      gateway.emit('status.update', const {'kind': 'loop'});
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 100));

      expect(gateway.controlReadCalls, readsBeforeLoopStatus + 1);
      // goal + loop + heartbeat + process. The pending task has its own
      // «Tareas» pill and is not counted as background work.
      expect(chat.sessionActivity.backgroundItemCount, 4);
      expect(chat.sessionActivity.active, isTrue);
      // The island counts the four; its card has one row for each.
      expect(_islandMark(tester), isNull);
      await _openRunningWork(tester);
      final card = find.byKey(const ValueKey('subagent-panel'));
      expect(card, findsOneWidget);
      Finder inCard(Finder what) => find.descendant(of: card, matching: what);
      Future<void> reveal(Finder what) async {
        await tester.ensureVisible(what);
        await tester.pump();
        await tester.pump(const Duration(milliseconds: 100));
      }

      expect(
        inCard(find.text('Actividad')),
        findsOneWidget,
        reason:
            'one sheet owns all activity; pending tasks stay in the transcript',
      );
      // The process, with its Detener.
      await reveal(find.text('python worker.py'));
      expect(
        inCard(find.textContaining('Segundo plano', findRichText: true)),
        findsWidgets,
      );
      // The loop and the heartbeat, with what holds them back.
      await reveal(find.text('Bucle recurrente'));
      expect(
        inCard(
          find.textContaining(
            'Esperando a que termine la ejecución actual',
            findRichText: true,
          ),
        ),
        findsWidgets,
      );
      expect(
        inCard(
          find.textContaining(
            'Aplazado mientras el goal permanente está activo',
            findRichText: true,
          ),
        ),
        findsWidgets,
      );
      await reveal(find.text('Latido'));
      // The task of the turn is the transcript's, not the card's.
      expect(inCard(find.text('PUBLIC_PENDING_TASK')), findsNothing);
      // A loop has no button; nothing was done by opening the card.
      expect(gateway.controlActions, isEmpty);
      expect(gateway.killedProcesses, isEmpty);

      // Detener stops that process and nothing else; the card stays.
      await reveal(
        find.byKey(const ValueKey('running-process-stop-process-mixed')),
      );
      await tester.tap(
        find.byKey(const ValueKey('running-process-stop-process-mixed')),
      );
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 100));
