  testWidgets(
    'pt1215: el último turno con ediciones cierra con «archivos cambiados»',
    (tester) async {
      final gateway = _UiRewindGateway();
      final chat = await pumpChat(
        tester,
        connection: _remoteConn('conn-pt1215-changed'),
        desktopGateway: gateway,
        messages: const [
          {'role': 'user', 'content': 'PUBLIC_REQUEST'},
        ],
      );
      expect(
        await chat.send(
          fullText: 'PUBLIC_CHANGED_PARENT',
          model: 'hermes-agent',
          history: chat.messages,
        ),
        isTrue,
      );
      gateway.emit('message.start');
      for (final (id, path, diff) in const [
        ('call-ch-1', 'lib/a.dart', '@@ -1 +1,2 @@\n-a\n+b\n+c'),
        ('call-ch-2', 'README.md', '@@ -1 +1 @@\n-x\n+y'),
        ('call-ch-3', 'lib/a.dart', '@@ -5 +5 @@\n-d\n+e'),
      ]) {
        gateway.emit('tool.start', {
          'tool_id': id,
          'name': 'patch',
          'args': {'path': path},
        });
        gateway.emit('tool.complete', {
          'tool_id': id,
          'name': 'patch',
          'args': {'path': path},
          'inline_diff': diff,
          'result': const {'success': true},
        });
      }
      // Every edit finished but no reply text yet: no summary in this frame.
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 400));
      expect(find.textContaining('PUBLIC_CHANGED_PARTIAL'), findsNothing);
      expect(find.byType(TurnChangesChip), findsNothing);
      gateway.emit('message.delta', const {'text': 'PUBLIC_CHANGED_PARTIAL'});
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 400));
      // Still working (the reply is streaming): no summary yet.
      expect(find.textContaining('PUBLIC_CHANGED_PARTIAL'), findsWidgets);
      expect(find.byType(TurnChangesChip), findsNothing);
      gateway.emit('message.complete', const {'text': 'PUBLIC_CHANGED_DONE'});
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 400));
      expect(find.byType(TurnChangesChip), findsOneWidget);
      // lib/a.dart +3 −2 across two edits, README.md +1 −1.
      expect(find.text('Δ 2 archivos · +4 −3'), findsOneWidget);
      expect(find.byType(FileDiffCard), findsNothing);

      final chip = find.byKey(const ValueKey('turn-changes-chip'));
      // Revealed the way the app reveals what must stay in reach, inside the
      // list's own padding (gint69, see [_revealInChatList]).
      await _revealInChatList(tester, chip);
      // Within reach: clear of the bottom group (gint67: the tap missed it).
      final chipRect = tester.getRect(chip);
      final bars = tester.getRect(
        find.byKey(const ValueKey('chat-bottom-bars')),
      );
      final pills = find.byKey(const ValueKey('delegates-capsule'));
      final view = tester.view.physicalSize / tester.view.devicePixelRatio;
      expect(
        chipRect.bottom,
        lessThanOrEqualTo(bars.top),
        reason:
            'chip $chipRect, bars $bars, '
            'pills ${pills.evaluate().length}, view $view',
      );
      await tester.tap(chip);
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 300));
      expect(find.byKey(const ValueKey('turn-changes-sheet')), findsOneWidget);
      expect(find.text('2 archivos cambiados'), findsOneWidget);
      expect(
        find.descendant(
          of: find.byKey(const ValueKey('turn-changes-file-0')),
          matching: find.text('+3 −2'),
        ),
        findsOneWidget,
      );
      expect(
        find.descendant(
          of: find.byKey(const ValueKey('turn-changes-file-1')),
          matching: find.text('README.md'),
        ),
        findsOneWidget,
      );
      // Both edits of lib/a.dart, in order, under their own line bands.
      expect(find.text('Líneas 1–2'), findsOneWidget);
      expect(find.text('Línea 5'), findsOneWidget);
      expect(find.byType(FileDiffBody), findsNothing);
      expect(tester.takeException(), isNull);
    },
  );

  // gint69: «archivos cambiados» closes the last turn ABOVE the bottom group
  // (composer and its foot), as the reader finds it when the turn ends, and
  // the finger reaches it: the list reserves the group's measured height as
  // its bottom padding.
  for (final size in const [Size(800, 600), Size(360, 640), Size(412, 915)]) {
    for (final scale in const [1.0, 1.3]) {
      final name = '${size.width.toInt()}x${size.height.toInt()}';
      testWidgets(
        'pt1215: at $name, text ${scale}x, «archivos cambiados» rests above '
        'the bottom group, within reach',
        (tester) async {
          tester.view.physicalSize = size;
          tester.view.devicePixelRatio = 1;
          tester.platformDispatcher.textScaleFactorTestValue = scale;
          addTearDown(tester.view.resetPhysicalSize);
          addTearDown(tester.view.resetDevicePixelRatio);
          addTearDown(tester.platformDispatcher.clearTextScaleFactorTestValue);
          final gateway = _UiRewindGateway();
          final chat = await pumpChat(
            tester,
            connection: _remoteConn('conn-pt1215-geometry-$name-$scale'),
            desktopGateway: gateway,
            messages: const [
              {'role': 'user', 'content': 'PUBLIC_REQUEST'},
            ],
          );
          expect(
            await chat.send(
              fullText: 'PUBLIC_CHANGED_PARENT',
              model: 'hermes-agent',
              history: chat.messages,
            ),
            isTrue,
          );
          _emitThreePatchTurn(gateway);
          await tester.pump();
          await tester.pump(const Duration(milliseconds: 400));
          gateway.emit('message.complete', const {
            'text': 'PUBLIC_CHANGED_DONE',
          });
          await tester.pump();
          await tester.pump(const Duration(milliseconds: 400));

          // At rest, no reveal: where the reader finds it.
          final chip = find.byKey(const ValueKey('turn-changes-chip'));
          expect(chip, findsOneWidget);
          final chipRect = tester.getRect(chip);
          final bars = tester.getRect(
            find.byKey(const ValueKey('chat-bottom-bars')),
          );
          expect(
            chipRect.bottom,
            lessThanOrEqualTo(bars.top),
            reason: 'chip $chipRect, bars $bars',
          );
          expect(chipRect.top, greaterThanOrEqualTo(0));
          await tester.tap(chip);
          await tester.pump();
          await tester.pump(const Duration(milliseconds: 300));
          expect(
            find.byKey(const ValueKey('turn-changes-sheet')),
            findsOneWidget,
          );
          expect(tester.takeException(), isNull);
        },
      );
    }
  }

