          },
          {'role': 'user', 'content': 'Pregunta histórica única'},
        ],
      );
      expect(gateway.resumeExistingCalls, greaterThan(0));
      gateway.resumeExistingError = null;

      await chat.send(
        fullText: 'Petición nueva todavía sin delta',
        model: 'hermes-agent',
        history: const [],
      );
