      await stt.emitFinalAndClose('parcial oculto');
      await tester.pump();
      expect(
        tester.widget<TextField>(find.byType(TextField)).controller!.text,
        'parcial oculto',
      );
      expect(find.byKey(const ValueKey('recording')), findsNothing);
      semantics.dispose();
    },
  );

